1	// src/lib/plattform/client.js
2	//
3	// fetch-Helfer für Client-Komponenten. Mutationen immer als JSON (CSRF-Schutz
4	// über Content-Type + Origin, siehe server/route.js); Uploads mit Kopfzeile.
5	
6	export async function senden(url, { method = "POST", body } = {}) {
7	  let res;
8	  try {
9	    res = await fetch(url, {
10	      method,
11	      headers: body !== undefined ? { "Content-Type": "application/json" } : undefined,
12	      body: body !== undefined ? JSON.stringify(body) : undefined,
13	      credentials: "same-origin",
14	      cache: "no-store",
15	    });
16	  } catch {
17	    throw new Error("Keine Verbindung – bitte prüfen Sie Ihre Internetverbindung.");
18	  }
19	  const json = await res.json().catch(() => ({}));
20	  if (!res.ok || json.ok === false) {
21	    const e = new Error(json.error || `Fehler ${res.status}`);
22	    e.status = res.status;
23	    throw e;
24	  }
25	  return json;
26	}
27	
28	export async function hochladen(datei, { bezugArt, bezugId, kategorie = "allgemein", checkliste = "", anhang = false }) {
29	  const fd = new FormData();
30	  fd.append("datei", datei);
31	  fd.append("bezugArt", bezugArt);
32	  fd.append("bezugId", bezugId);
33	  fd.append("kategorie", kategorie);
34	  if (checkliste) fd.append("checkliste", checkliste);
35	  if (anhang) fd.append("anhang", "1"); // Querschnitt: Anhang einer Nachricht
36	  const res = await fetch("/api/portal/dokumente", { method: "POST", body: fd, headers: { "X-Plattform-Upload": "1" }, credentials: "same-origin" });
37	  const json = await res.json().catch(() => ({}));
38	  if (!res.ok || json.ok === false) throw new Error(json.error || `Upload fehlgeschlagen (${res.status})`);
39	  return json.dokument;
40	}
