42	// Basis nur zum Auflösen relativer Pfade; .invalid ist reserviert (RFC 2606) und nie erreichbar.
43	const ZIEL_BASIS = "https://ziel.invalid";
44	// Unsicher: Steuerzeichen (C0/C1), Leerzeichen, Unicode-Leer-, Zero-Width- und Richtungszeichen, BOM, Backslash.
45	// Als Codepunkte geprüft, damit keine unsichtbaren Zeichen im Quelltext stehen.
46	function unsicheresZeichen(s) {
47	  for (const c of s) {
48	    const n = c.codePointAt(0);
49	    if (n <= 0x20 || (n >= 0x7f && n <= 0xa0) || n === 0x5c || n === 0x1680 || n === 0x3000 || n === 0xfeff) return true;
50	    if ((n >= 0x2000 && n <= 0x200f) || (n >= 0x2028 && n <= 0x202f) || (n >= 0x205f && n <= 0x206f)) return true;
51	  }
52	  return false;
53	}
54	
55	/**
56	 * Nur interne Pfade als Ziel nach dem Login zulassen (kein Open Redirect).
57	 *
58	 * Browser entfernen beim URL-Parsen Tab/CR/LF und deuten "\" wie "/" (WHATWG URL Standard):
59	 * "/\t/evil.com" wird so zu "//evil.com" und damit zu https://evil.com. Deshalb werden Steuer-,
60	 * Leerzeichen und Backslashes komplett abgelehnt, und das Ergebnis wird zusätzlich aufgelöst
61	 * und muss auf derselben Herkunft bleiben. Zurück kommt der normalisierte Pfad
62	 * (z. B. "/x/../api/…" wird als "/api/…" erkannt und abgelehnt).
63	 * Test: node --test src/lib/plattform/sicheresZiel.test.mjs
64	 */
65	export function sicheresZiel(weiter, standard = "/portal") {
66	  const w = String(weiter || "");
67	  if (!w.startsWith("/") || w.startsWith("//") || unsicheresZeichen(w)) return standard;
68	  let u;
69	  try {
70	    u = new URL(w, ZIEL_BASIS);
71	  } catch {
72	    return standard;
73	  }
74	  if (u.origin !== ZIEL_BASIS) return standard;
75	  const pfad = `${u.pathname}${u.search}${u.hash}`;
76	  return /^\/api(\/|$)/i.test(u.pathname) ? standard : pfad;
77	}
