1	// src/lib/plattform/backend/index.js
2	//
3	// Einheitliche Backend-Schnittstelle der Plattform. Zwei Implementierungen:
4	//   frappe.js – Frappe-App `oekoinvest_app` (Produktion), Auswahl mit PLATTFORM_BACKEND=frappe
5	//   demo.js   – JSON-Datei unter .data/plattform.json (Entwicklung/Vorführung)
6	//
7	// Im Produktions-Build wird das Demo-Backend NUR genutzt, wenn PLATTFORM_DEMO=1 gesetzt ist –
8	// sonst gibt es eine klare Fehlermeldung (HTTP 503) statt stiller Demo-Daten.
9	//
10	// Nur serverseitig verwenden (Route-Handler, Server-Komponenten).
11	//
12	// Alle Operationen (Signaturen identisch in beiden Implementierungen; n = angemeldeter Nutzer):
13	//   Konto:     anmelden({email,passwort}) · nutzerFuerSitzung(id) · registrieren({...}) · emailBestaetigen({token})
14	//              passwortVergessen({email,basisUrl,ip}) · passwortSetzen({token,passwort,ip}) · passwortAendern(n,{alt,neu})
15	//              profilSpeichern(n,daten) · suchprofilSpeichern(n,profil)
16	//   Anfrage:   anfrageAnlegen({typ,kontakt,daten,herkunft,ip,einwilligungText,nutzer})
17	//   Vorgänge:  vorgaenge(n,{alle,status,typ,q}) · vorgang(n,id)
18	//   Flächen:   flaechen(n,{alle,status}) · flaeche(n,id) · flaecheAnlegen(n,daten,{ip}) · flaecheAendern(n,id,daten)
19	//   Projekte:  projekte(n,{alle,status}) · projekt(n,id) · projektAnlegen(n,daten,{ip}) · projektAendern(n,id,daten)
20	//              provisionAkzeptieren(n,id,{ip})
21	//   Börse:     boerse(n|null,filter) · boerseDetail(n|null,slugOderId,{zaehlen})
22	//   Interesse: merken(n,projektId,an) · ndaAnfragen(n,projektId,{akzeptiert,ip,userAgent}) · interessen(n,{alle,status,projektId})
23	//   Prozess:   statusWechsel(n,{art,id,nach,als,extra,ip})
24	//   Nachricht: nachrichtenThreads(n) · nachrichten(n,bezugArt,bezugId,{markieren}) · nachrichtSenden(n,{bezugArt,bezugId,text})
25	//   Dokument:  dokumente(n,{bezugArt,bezugId}) · dokumentLesen(n,id) · dokumentSpeichern(n,{...,daten}) · dokumentLoeschen(n,id)
26	//   Admin:     zuweisen · nutzerListe · nutzerAendern · provisionen · aktivitaeten · adminKonten · adminUebersicht · demoLinks
27	//   Hinweise:  benachrichtigungen(n,{nurUngelesen,limit}) · benachrichtigungenGelesen(n,{ids,alle}) · mailEinstellungenSpeichern(n,einstellungen)
28	//   Aufgaben:  aufgaben(n,{zustaendigId,status,bezugArt,bezugId,nurUeberfaellig}) · aufgabeAnlegen(n,daten) · aufgabeAendern(n,id,daten)
29	//   Exposé:    exposeDaten(n,id,{ip}) (Rechte + Protokoll, PDF erzeugt die Website) · protokollEintrag(n,{aktion,objektArt,objektId,text,ip})
30	//   Nur Demo:  postausgang(n,{limit}) (E-Mails, die Frappe versenden würde; im Frappe-Adapter [])
31	
32	import * as demo from "./demo";
33	import * as frappe from "./frappe";
34	import { PlattformFehler } from "../fehler";
35	import { BACKOFFICE_OPERATIONEN } from "./frappe/backoffice";
36	import { demoPruefung } from "../demoGuard";
37	
38	export const OPERATIONEN = [
39	  "anmelden", "nutzerFuerSitzung", "registrieren", "emailBestaetigen", "passwortVergessen", "passwortSetzen", "passwortAendern",
40	  "profilSpeichern", "suchprofilSpeichern", "anfrageAnlegen", "vorgaenge", "vorgang", "flaechen", "flaeche", "flaecheAnlegen",
41	  "flaecheAendern", "projekte", "projekt", "projektAnlegen", "projektAendern", "provisionAkzeptieren", "boerse", "boerseDetail",
42	  "merken", "ndaAnfragen", "interessen", "statusWechsel", "nachrichtenThreads", "nachrichten", "nachrichtSenden", "dokumente",
43	  "dokumentLesen", "dokumentSpeichern", "dokumentLoeschen", "zuweisen", "nutzerListe", "nutzerAendern", "provisionen",
44	  "aktivitaeten", "adminKonten", "adminUebersicht", "demoLinks", "benachrichtigungen", "benachrichtigungenGelesen",
45	  "mailEinstellungenSpeichern", "postausgang", "aufgaben", "aufgabeAnlegen", "aufgabeAendern", "exposeDaten", "protokollEintrag",
46	  ...BACKOFFICE_OPERATIONEN, // Backoffice: CRM, Akquise, Automationen, Vorlagen, Berichte, Rechte (backend/frappe/backoffice.js)
47	];
48	
49	if (process.env.NODE_ENV !== "production") {
50	  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
51	    const fehlt = OPERATIONEN.filter((op) => typeof impl[op] !== "function");
52	    if (fehlt.length) console.warn(`[plattform] Backend ${name}: fehlende Operationen ${fehlt.join(", ")}`);
53	  }
54	}
55	
56	export const KONFIG_FEHLER =
57	  "Das Plattform-Backend ist nicht konfiguriert. Für den Betrieb PLATTFORM_BACKEND=frappe setzen (siehe docs/PLATTFORM.md) – oder PLATTFORM_DEMO=1 für eine reine Vorführung.";
58	
59	let demoSperreGemeldet = false;
60	
61	export function backendName() {
62	  if (process.env.PLATTFORM_BACKEND === "frappe") return "frappe";
63	  // Demo-Guard (Paket A): im Produktions-Build nie auf der Produktionsdomain, nie ohne Basis-URL
64	  const pruefung = demoPruefung();
65	  if (!pruefung.erlaubt) {
66	    if (process.env.PLATTFORM_DEMO === "1" && !demoSperreGemeldet) {
67	      demoSperreGemeldet = true;
68	      console.error(`[plattform] Demo-Backend gesperrt: ${pruefung.grund}`);
69	    }
70	    return null;
71	  }
72	  return "demo";
73	}
74	
75	/** Liefert die aktive Implementierung oder wirft 503 */
76	export function backend() {
77	  const n = backendName();
78	  if (n === "frappe") return frappe;
79	  if (n === "demo") return demo;
80	  throw new PlattformFehler(503, KONFIG_FEHLER);
81	}
82	
83	export const istDemo = () => backendName() === "demo";
