1	// src/lib/plattform/fehler.js
2	//
3	// Einheitlicher Fehler für Backend und API. `status` wird 1:1 als HTTP-Status
4	// zurückgegeben, `message` ist für Nutzer bestimmt (deutsch, ohne Interna).
5	
6	const CODES = {
7	  400: "ungueltig",
8	  401: "nicht_angemeldet",
9	  403: "verboten",
10	  404: "nicht_gefunden",
11	  409: "konflikt",
12	  413: "zu_gross",
13	  415: "typ",
14	  422: "validierung",
15	  429: "zu_viele",
16	  502: "backend",
17	  503: "nicht_konfiguriert",
18	};
19	
20	export class PlattformFehler extends Error {
21	  constructor(status, message, code) {
22	    super(message);
23	    this.name = "PlattformFehler";
24	    this.status = status;
25	    this.code = code || CODES[status] || "fehler";
26	  }
27	}
28	
29	export const nichtAngemeldet = () => new PlattformFehler(401, "Bitte melden Sie sich an.");
30	export const verboten = (text = "Dafür fehlt Ihnen die Berechtigung.") => new PlattformFehler(403, text);
31	export const nichtGefunden = (text = "Nicht gefunden.") => new PlattformFehler(404, text);
32	export const ungueltig = (text) => new PlattformFehler(422, text);
33	export const konflikt = (text) => new PlattformFehler(409, text);
