1	// src/lib/plattform/backend/frappe.js
2	//
3	// Frappe-Backend: spricht die Frappe-App `oekoinvest_app` über whitelisted Methoden an.
4	// Vertrag (Methoden, Felder, Rechte, Fehler): docs/API.md.
5	//
6	//  - Server-zu-Server mit API-Key/Secret (SERVER, API_KEY, API_SECRET wie src/lib/apiBaseUrl.js).
7	//    Der API-Nutzer hat in Frappe nur die Rolle „ÖkoInvest API“.
8	//  - Aktionen im Namen des eingeloggten Nutzers: jedes Argument-Objekt enthält `als_benutzer`
9	//    (Konto-ID `nutzer.id`, z. B. U-26-7KQ2XM). Die Frappe-App löst daraus den Frappe-User auf,
10	//    wechselt per frappe.set_user() in den Nutzer und prüft Rolle UND Eigentum selbst –
11	//    die Next.js-Seite ist nur die erste Verteidigungslinie.
12	//  - Argumente und Antworten in camelCase-JSON, identisch zum Demo-Backend.
13	//  - Liefert eine Methode `None` (z. B. anmelden mit falschen Daten), fehlt `message` in der
14	//    Frappe-Antwort – der Adapter gibt dann `null` zurück (wie das Demo-Backend).
15	
16	import { API_BASE_URL, getApiHeaders, isApiConfigured } from "@/lib/apiBaseUrl";
17	import { PlattformFehler } from "../fehler";
18	
19	export const name = "frappe";
20	
21	const PRAEFIX = "oekoinvest_app.plattform.api.";
22	const TIMEOUT_MS = 15000;
