83	function meldung(daten) {
84	  let text = "";
85	  try {
86	    const liste = JSON.parse(daten?._server_messages || "[]");
87	    text = JSON.parse(liste[0] || "{}").message || "";
88	  } catch {
89	    /* keine Servermeldung */
90	  }
91	  if (!text && typeof daten?.exception === "string") text = daten.exception.replace(/^[\w.]*(Error|Exception):\s*/, "");
92	  return text.replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim().slice(0, 240);
93	}
