95	export async function aufruf(op, args = {}, nutzer = null) {
96	  if (!isApiConfigured() || !process.env.SERVER) {
97	    throw new PlattformFehler(503, "Das Plattform-Backend (Frappe) ist nicht konfiguriert.");
98	  }
99	  const url = `${API_BASE_URL}${PRAEFIX}${METHODEN[op]}`;
100	  let res;
101	  try {
102	    res = await fetch(url, {
103	      method: "POST",
104	      headers: getApiHeaders(),
105	      // als_organisation: aktive Organisation der Sitzung – Frappe prüft die Mitgliedschaft selbst (kern.nutzer)
106	      body: JSON.stringify({ ...args, ...(nutzer ? { als_benutzer: nutzer.id } : {}), ...(nutzer?.organisation?.id ? { als_organisation: nutzer.organisation.id } : {}) }),
107	      cache: "no-store",
108	      signal: AbortSignal.timeout(TIMEOUT_MS),
109	    });
110	  } catch (e) {
111	    console.error(`[plattform-frappe] ${op}: nicht erreichbar`, e?.message);
112	    throw new PlattformFehler(502, "Der Server ist vorübergehend nicht erreichbar.");
113	  }
114	  if (res.ok) {
115	    const j = await res.json().catch(() => ({}));
116	    return j.message ?? null;
117	  }
118	  const roh = await res.text().catch(() => "");
119	  let daten = {};
120	  try {
121	    daten = JSON.parse(roh);
122	  } catch {
123	    daten = {};
124	  }
125	  // Interna (Traceback) nur ins Server-Log – nie an den Browser
126	  console.error(`[plattform-frappe] ${op}: HTTP ${res.status} ${daten.exc_type || ""}`);
127	  const text = meldung(daten);
128	  const typ = String(daten.exc_type || "");
129	  if (res.status === 401 || /AuthenticationError/.test(typ)) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
130	  if (res.status === 403 || /PermissionError/.test(typ)) throw new PlattformFehler(403, text || "Dafür fehlt Ihnen die Berechtigung.");
131	  if (res.status === 404 || /DoesNotExistError/.test(typ)) throw new PlattformFehler(404, text || "Nicht gefunden.");
132	  if (/KycErforderlich/.test(typ)) throw new PlattformFehler(409, text || "Bitte Verifizierung abschließen.", "kyc"); // KYC/KYB: Freigabe-Sperre (plattform/kyc_kern.py)
133	  if (/BonitaetErforderlich/.test(typ)) throw new PlattformFehler(409, text || "Vor LOI bzw. Gebot ist eine Bonitätsprüfung nötig.", "bonitaet"); // Dienste: Bonität vor LOI (plattform/dienste_kern.py)
134	  if (res.status === 409 || /DuplicateEntryError|TimestampMismatchError/.test(typ)) throw new PlattformFehler(409, text || "Konflikt – bitte neu laden.");
135	  if (res.status === 429 || /TooManyRequestsError/.test(typ)) throw new PlattformFehler(429, text || "Zu viele Anfragen – bitte warten Sie einen Moment.", "gesperrt");
136	  if (/ValidationError|MandatoryError|LinkValidationError/.test(typ) || res.status === 417) throw new PlattformFehler(422, text || "Eingabe ungültig.");
137	  throw new PlattformFehler(502, "Der Server ist vorübergehend nicht erreichbar.");
138	}
