2	//
3	// Einfaches Rate-Limit im Arbeitsspeicher (gleitendes Fenster je Schlüssel).
4	// Reicht für einen einzelnen Node-Prozess; bei mehreren Instanzen zusätzlich
5	// am Reverse-Proxy (nginx limit_req) begrenzen – siehe docs/PLATTFORM.md.
6	
7	import { PlattformFehler } from "../fehler";
8	
9	const speicher = (globalThis.__oiRateLimit ||= new Map());
10	
11	/** Wirft 429, wenn `schluessel` mehr als `max` Treffer im Fenster hat */
12	export function rateLimit(schluessel, max, fensterMs) {
13	  const jetzt = Date.now();
14	  const liste = (speicher.get(schluessel) || []).filter((t) => jetzt - t < fensterMs);
15	  if (liste.length >= max) {
16	    speicher.set(schluessel, liste);
17	    throw new PlattformFehler(429, "Zu viele Versuche in kurzer Zeit – bitte warten Sie einige Minuten.");
18	  }
19	  liste.push(jetzt);
20	  speicher.set(schluessel, liste);
21	
22	  // gelegentlich aufräumen
23	  if (speicher.size > 5000) {
24	    for (const [k, v] of speicher) if (!v.length || jetzt - v[v.length - 1] > 3600e3) speicher.delete(k);
25	  }
26	}
27	
28	/** Grenzen je Aktion: [max, Fenster in ms] */
29	export const GRENZEN = {
30	  login: [10, 15 * 60e3],
31	  loginEmail: [8, 15 * 60e3],
32	  registrieren: [5, 60 * 60e3],
33	  anfrage: [10, 60 * 60e3],
34	  passwort: [5, 60 * 60e3],
35	  upload: [60, 60 * 60e3],
36	  nachricht: [120, 60 * 60e3],
37	  // Login, Sicherheit & Teams
38	  magicLink: [5, 60 * 60e3],
39	  zweiFaktor: [10, 15 * 60e3],
40	  einladung: [30, 60 * 60e3],
41	  export: [10, 60 * 60e3],
42	};
43	
44	/**
45	 * In der Entwicklung sind die Grenzen 10-fach gelockert (wiederholte Testläufe),
46	 * über PLATTFORM_RATE_FAKTOR einstellbar. In Produktion gilt immer Faktor 1.
47	 */
48	export function grenze(name) {
49	  const [max, fenster] = GRENZEN[name];
50	  const faktor = process.env.NODE_ENV !== "production" ? Number(process.env.PLATTFORM_RATE_FAKTOR) || 10 : 1;
51	  return [Math.max(1, Math.round(max * faktor)), fenster];
52	}
