// Exploration: API.md vs Code (Frappe-Methoden, HTTP-Routen)
import fs from "node:fs";
import path from "node:path";

const ROOT = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web";
const API_MD = fs.readFileSync(path.join(ROOT, "docs/API.md"), "utf8");
const PY_DIR = path.join(ROOT, "Backend-Import/oekoinvest_app/oekoinvest_app/plattform/api");
const FRAPPE_DIR = path.join(ROOT, "src/lib/plattform/backend");
const APP_API = path.join(ROOT, "src/app/api");

// --- 1. Adapter-Methoden (frappe.js + frappe/*.js) ----------------------------------
const adapterDateien = [path.join(FRAPPE_DIR, "frappe.js"), ...fs.readdirSync(path.join(FRAPPE_DIR, "frappe")).filter(f => f.endsWith(".js")).map(f => path.join(FRAPPE_DIR, "frappe", f))];
const methoden = new Map(); // "mod.fn" -> datei
for (const d of adapterDateien) {
  const t = fs.readFileSync(d, "utf8");
  for (const m of t.matchAll(/:\s*"([a-z0-9_]+\.[a-z0-9_]+)"/g)) methoden.set(m[1], path.basename(d));
}
console.log("Adapter-Methoden:", methoden.size);

// Python-Funktionen je Modul
const pyFunktionen = new Map();
for (const f of fs.readdirSync(PY_DIR).filter(f => f.endsWith(".py"))) {
  const t = fs.readFileSync(path.join(PY_DIR, f), "utf8");
  const fns = new Set();
  for (const m of t.matchAll(/^def ([a-z0-9_]+)\(/gm)) fns.add(m[1]);
  pyFunktionen.set(f.replace(/\.py$/, ""), { fns, text: t });
}

let fehler = [];
for (const [mf, datei] of methoden) {
  const [mod, fn] = mf.split(".");
  const py = pyFunktionen.get(mod);
  if (!py) { fehler.push(`FEHLT-MODUL: ${mf} (Adapter ${datei}) – kein api/${mod}.py`); continue; }
  if (!py.fns.has(fn)) fehler.push(`FEHLT-FUNKTION: ${mf} (Adapter ${datei})`);
}
// Adapter-Methode in API.md dokumentiert?
for (const [mf, datei] of methoden) {
  if (!API_MD.includes(mf)) fehler.push(`UNDOKUMENTIERT: ${mf} (Adapter ${datei}) fehlt in docs/API.md`);
}

// --- 2. API.md-Methoden -> Python ----------------------------------------------------
const docMethoden = new Set();
for (const m of API_MD.matchAll(/`([a-z0-9_]+)\.([a-z0-9_]+)`/g)) {
  if (pyFunktionen.has(m[1])) docMethoden.add(`${m[1]}.${m[2]}`);
}
for (const mf of docMethoden) {
  const [mod, fn] = mf.split(".");
  if (!pyFunktionen.get(mod).fns.has(fn)) fehler.push(`DOC-OHNE-PY: ${mf} in API.md, aber keine Funktion in api/${mod}.py`);
}

// --- 3. HTTP-Routen in API.md -> src/app/api -----------------------------------------
function routeExistiert(p) {
  // p wie /api/portal/flaechen/[id]
  const segs = p.replace(/^\/api\//, "").split("/").filter(Boolean);
  let dir = APP_API;
  for (const s of segs) {
    const kandidaten = fs.existsSync(dir) ? fs.readdirSync(dir) : [];
    if (kandidaten.includes(s)) { dir = path.join(dir, s); continue; }
    if (s.startsWith("[")) {
      const dyn = kandidaten.find(k => k.startsWith("["));
      if (dyn) { dir = path.join(dir, dyn); continue; }
    } else {
      const dyn = kandidaten.find(k => k.startsWith("["));
      if (dyn) { dir = path.join(dir, dyn); continue; } // Doku nennt konkreten Wert, Route ist dynamisch
    }
    return false;
  }
  return fs.existsSync(path.join(dir, "route.js"));
}
const docRouten = new Set();
for (const m of API_MD.matchAll(/`(?:GET |POST |PATCH |PUT |DELETE |GET, POST |GET\|POST )?(\/api\/[A-Za-z0-9\-_\/\[\]|.…]+)/g)) {
  let p = m[1].replace(/[?#].*$/, "");
  docRouten.add(p);
}
console.log("Dokumentierte Routen:", docRouten.size);
for (const p of [...docRouten].sort()) {
  if (p.includes("…") || p.includes("|") || p.includes("[/")) { console.log("ÜBERSPRUNGEN (Notation):", p); continue; }
  if (!routeExistiert(p)) fehler.push(`ROUTE-FEHLT: ${p}`);
}

// --- 4. Routen im Code, die in API.md fehlen ------------------------------------------
function alleRouten(dir, prefix) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) out.push(...alleRouten(path.join(dir, e.name), `${prefix}/${e.name}`));
    else if (e.name === "route.js") out.push(prefix);
  }
  return out;
}
const codeRouten = alleRouten(APP_API, "/api");
console.log("Code-Routen gesamt:", codeRouten.length);
const PLATTFORM_PREFIXE = ["/api/portal", "/api/admin", "/api/auth", "/api/boerse", "/api/anfrage", "/api/angebot", "/api/dienste", "/api/eg"];
for (const r of codeRouten) {
  if (!PLATTFORM_PREFIXE.some(p => r === p || r.startsWith(p + "/"))) continue;
  // in API.md erwähnt? (mit dynamischen Segmenten tolerant: exakter Teilstring)
  if (!API_MD.includes(r)) fehler.push(`ROUTE-UNDOKUMENTIERT: ${r}`);
}

console.log("\n=== BEFUNDE:", fehler.length, "===");
for (const f of fehler.sort()) console.log(f);

