import fs from "node:fs";
import path from "node:path";
const ROOT = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web";
const PY_DIR = path.join(ROOT, "Backend-Import/oekoinvest_app/oekoinvest_app/plattform/api");
const FRAPPE_DIR = path.join(ROOT, "src/lib/plattform/backend");
const docs = [];
for (const d of ["docs", "docs/eg", "docs/handbuch", "docs/fachpruefung"]) {
  const dir = path.join(ROOT, d);
  if (!fs.existsSync(dir)) continue;
  for (const f of fs.readdirSync(dir)) if (f.endsWith(".md")) docs.push(fs.readFileSync(path.join(dir, f), "utf8"));
}
const ALLE = docs.join("\n");

const adapterDateien = [path.join(FRAPPE_DIR, "frappe.js"), ...fs.readdirSync(path.join(FRAPPE_DIR, "frappe")).filter((f) => f.endsWith(".js")).map((f) => path.join(FRAPPE_DIR, "frappe", f))];
const methoden = new Map();
for (const d of adapterDateien) {
  const t = fs.readFileSync(d, "utf8");
  for (const m of t.matchAll(/:\s*"([a-z0-9_]+\.[a-z0-9_]+)"/g)) methoden.set(m[1], path.basename(d));
}
// tolerant: voll dokumentiert ODER Funktionsname in Backticks irgendwo
let undok = [];
for (const [mf, datei] of methoden) {
  const [, fn] = mf.split(".");
  if (ALLE.includes(mf)) continue;
  if (new RegExp("[`.\\s/|·]" + fn + "[`\\s(,}|·]").test(ALLE)) continue;
  undok.push(`${mf} (${datei})`);
}
console.log("Adapter-Methoden gesamt:", methoden.size, "— nirgends dokumentiert:", undok.length);
for (const u of undok.sort()) console.log("  ", u);

// Whitelist-Decorator vorhanden?
let ohneWhitelist = [];
const pyCache = new Map();
for (const [mf] of methoden) {
  const [mod, fn] = mf.split(".");
  if (!pyCache.has(mod)) pyCache.set(mod, fs.readFileSync(path.join(PY_DIR, mod + ".py"), "utf8"));
  const t = pyCache.get(mod);
  const idx = t.search(new RegExp(`^def ${fn}\\(`, "m"));
  if (idx < 0) { ohneWhitelist.push(mf + " (fehlt ganz)"); continue; }
  const davor = t.slice(Math.max(0, idx - 400), idx);
  // Decorator-Block direkt über def: letzte Zeilen bis zur ersten Nicht-Decorator-Zeile
  const zeilen = davor.split("\n").slice(0, -1);
  let whitelisted = false;
  for (let i = zeilen.length - 1; i >= 0; i--) {
    const z = zeilen[i].trim();
    if (z.startsWith("@")) { if (z.includes("whitelist")) whitelisted = true; continue; }
    if (z === "" || z.startsWith("#")) continue;
    break;
  }
  if (!whitelisted) ohneWhitelist.push(mf);
}
console.log("\nOhne @frappe.whitelist:", ohneWhitelist.length);
for (const o of ohneWhitelist) console.log("  ", o);

